HISTORIAS.append({'id': 'lei-v2-9-11-11', 'faixa_etaria': '9-11', 'colecao': 'Descobertas do cotidiano', 'tema': 'Cotidiano e escolhas', 'titulo': 'A música em conjunto', 'nivel': 'basico', 'nivel_numerico': 2, 'vocabulario': [], 'paginas': ['Bia tocava muito rápido durante o ensaio. O grupo não conseguia acompanhar o ritmo.', 'Ela ouviu os colegas e todos combinaram marcar o tempo antes de tocar.', 'A música ficou mais organizada. Bia percebeu que ouvir o grupo era tão importante quanto tocar sua parte.'], 'perguntas': [{'id': 'lei-v2-9-11-11-q1', 'enunciado': 'Que problema ocorreu no ensaio?', 'alternativas': ['Uma viagem de trem', 'O grupo não acompanhava o ritmo', 'Um jogo na televisão', 'Uma festa na escola'], 'correta': 'O grupo não acompanhava o ritmo'}, {'id': 'lei-v2-9-11-11-q2', 'enunciado': 'O que combinaram?', 'alternativas': ['Marcar o tempo antes de tocar', 'Ignorar o problema', 'Mudar de assunto', 'Esperar sem fazer nada'], 'correta': 'Marcar o tempo antes de tocar'}, {'id': 'lei-v2-9-11-11-q3', 'enunciado': 'O que Bia percebeu?', 'alternativas': ['Nada mudou', 'Todos esqueceram o assunto', 'O problema foi escondido', 'Ouvir o grupo também era importante'], 'correta': 'Ouvir o grupo também era importante'}], 'reflexao': 'Qual decisão você tomaria nessa situação? Explique usando uma informação da história.'})
HISTORIAS.append({'id': 'lei-v2-9-11-12', 'faixa_etaria': '9-11', 'colecao': 'Descobertas do cotidiano', 'tema': 'Cotidiano e escolhas', 'titulo': 'O cartaz legível', 'nivel': 'basico', 'nivel_numerico': 2, 'vocabulario': [], 'paginas': ['Nina fez um cartaz para a exposição, mas usou letras pequenas. Quem passava não conseguia ler.', 'Ela aumentou as letras e organizou as informações em poucas frases.', 'Os visitantes passaram a ler o cartaz de longe. Nina guardou o modelo para a próxima exposição.'], 'perguntas': [{'id': 'lei-v2-9-11-12-q1', 'enunciado': 'Por que era difícil ler o cartaz?', 'alternativas': ['As letras eram pequenas', 'Um jogo na televisão', 'Uma festa na escola', 'Uma viagem de trem'], 'correta': 'As letras eram pequenas'}, {'id': 'lei-v2-9-11-12-q2', 'enunciado': 'Que mudança Nina fez?', 'alternativas': ['Ignorar o problema', 'Mudar de assunto', 'Esperar sem fazer nada', 'Aumentou as letras'], 'correta': 'Aumentou as letras'}, {'id': 'lei-v2-9-11-12-q3', 'enunciado': 'Qual foi o resultado?', 'alternativas': ['Todos esqueceram o assunto', 'O problema foi escondido', 'Os visitantes leram de longe', 'Nada mudou'], 'correta': 'Os visitantes leram de longe'}], 'reflexao': 'Qual decisão você tomaria nessa situação? Explique usando uma informação da história.'})
