HISTORIAS.append({'id': 'lei-v2-9-11-15', 'faixa_etaria': '9-11', 'colecao': 'Descobertas do cotidiano', 'tema': 'Cotidiano e escolhas', 'titulo': 'O desenho compartilhado', 'nivel': 'basico', 'nivel_numerico': 2, 'vocabulario': [], 'paginas': ['Davi e Rita queriam desenhar no mesmo papel. Cada um puxava a folha para seu lado.', 'Eles combinaram dividir o espaço e escolher juntos o tema do desenho.', 'No fim, criaram um jardim com ideias dos dois. A combinação permitiu trabalhar em conjunto.'], 'perguntas': [{'id': 'lei-v2-9-11-15-q1', 'enunciado': 'Qual era a dificuldade inicial?', 'alternativas': ['Uma viagem de trem', 'Cada um puxava a folha', 'Um jogo na televisão', 'Uma festa na escola'], 'correta': 'Cada um puxava a folha'}, {'id': 'lei-v2-9-11-15-q2', 'enunciado': 'O que combinaram?', 'alternativas': ['Dividir o espaço e escolher o tema', 'Ignorar o problema', 'Mudar de assunto', 'Esperar sem fazer nada'], 'correta': 'Dividir o espaço e escolher o tema'}, {'id': 'lei-v2-9-11-15-q3', 'enunciado': 'O que desenharam?', 'alternativas': ['Nada mudou', 'Todos esqueceram o assunto', 'O problema foi escondido', 'Um jardim'], 'correta': 'Um jardim'}], 'reflexao': 'Qual decisão você tomaria nessa situação? Explique usando uma informação da história.'})
HISTORIAS.append({'id': 'lei-v2-9-11-16', 'faixa_etaria': '9-11', 'colecao': 'Descobertas do cotidiano', 'tema': 'Cotidiano e escolhas', 'titulo': 'O trajeto mais seguro', 'nivel': 'basico', 'nivel_numerico': 2, 'vocabulario': [], 'paginas': ['Leo conhecia um atalho para a escola, mas o caminho não tinha faixa de pedestres.', 'Com um adulto, escolheu um trajeto um pouco maior que passava pela faixa.', 'Ele chegou à escola pelo novo caminho. A decisão considerou a segurança, além da distância.'], 'perguntas': [{'id': 'lei-v2-9-11-16-q1', 'enunciado': 'O que faltava no atalho?', 'alternativas': ['Faixa de pedestres', 'Um jogo na televisão', 'Uma festa na escola', 'Uma viagem de trem'], 'correta': 'Faixa de pedestres'}, {'id': 'lei-v2-9-11-16-q2', 'enunciado': 'Qual trajeto escolheu?', 'alternativas': ['Ignorar o problema', 'Mudar de assunto', 'Esperar sem fazer nada', 'Um que passava pela faixa'], 'correta': 'Um que passava pela faixa'}, {'id': 'lei-v2-9-11-16-q3', 'enunciado': 'O que orientou a decisão?', 'alternativas': ['Todos esqueceram o assunto', 'O problema foi escondido', 'A segurança', 'Nada mudou'], 'correta': 'A segurança'}], 'reflexao': 'Qual decisão você tomaria nessa situação? Explique usando uma informação da história.'})
HISTORIAS.append({'id': 'lei-v2-9-11-17', 'faixa_etaria': '9-11', 'colecao': 'Descobertas do cotidiano', 'tema': 'Cotidiano e escolhas', 'titulo': 'A caixa de sementes', 'nivel': 'basico', 'nivel_numerico': 2, 'vocabulario': [], 'paginas': ['Ana guardou sementes de plantas diferentes em saquinhos iguais. Depois não lembrava qual era cada uma.', 'Ela pediu ajuda para identificar as sementes e escreveu etiquetas com os nomes.', 'Na próxima coleta, etiquetou os saquinhos antes de guardar. Assim, evitou a mesma confusão.'], 'perguntas': [{'id': 'lei-v2-9-11-17-q1', 'enunciado': 'Qual foi o problema?', 'alternativas': ['Um jogo na televisão', 'Uma festa na escola', 'Uma viagem de trem', 'Ana não lembrava qual era cada semente'], 'correta': 'Ana não lembrava qual era cada semente'}, {'id': 'lei-v2-9-11-17-q2', 'enunciado': 'Como organizou os saquinhos?', 'alternativas': ['Mudar de assunto', 'Esperar sem fazer nada', 'Com etiquetas de nomes', 'Ignorar o problema'], 'correta': 'Com etiquetas de nomes'}, {'id': 'lei-v2-9-11-17-q3', 'enunciado': 'O que mudou na próxima coleta?', 'alternativas': ['O problema foi escondido', 'Etiquetou antes de guardar', 'Nada mudou', 'Todos esqueceram o assunto'], 'correta': 'Etiquetou antes de guardar'}], 'reflexao': 'Qual decisão você tomaria nessa situação? Explique usando uma informação da história.'})
HISTORIAS.append({'id': 'lei-v2-9-11-18', 'faixa_etaria': '9-11', 'colecao': 'Descobertas do cotidiano', 'tema': 'Cotidiano e escolhas', 'titulo': 'A notícia conferida', 'nivel': 'basico', 'nivel_numerico': 2, 'vocabulario': [], 'paginas': ['Ivo recebeu uma mensagem dizendo que não haveria aula. A mensagem não tinha data nem fonte.', 'Antes de compartilhar, consultou o comunicado oficial da escola. As aulas estavam mantidas.', 'Ivo explicou aos colegas o que encontrou. Conferir a fonte evitou espalhar uma informação incorreta.'], 'perguntas': [{'id': 'lei-v2-9-11-18-q1', 'enunciado': 'O que faltava na mensagem?', 'alternativas': ['Uma festa na escola', 'Uma viagem de trem', 'Data e fonte', 'Um jogo na televisão'], 'correta': 'Data e fonte'}, {'id': 'lei-v2-9-11-18-q2', 'enunciado': 'Onde Ivo conferiu?', 'alternativas': ['Esperar sem fazer nada', 'No comunicado oficial da escola', 'Ignorar o problema', 'Mudar de assunto'], 'correta': 'No comunicado oficial da escola'}, {'id': 'lei-v2-9-11-18-q3', 'enunciado': 'O que evitou ao conferir?', 'alternativas': ['Espalhar informação incorreta', 'Nada mudou', 'Todos esqueceram o assunto', 'O problema foi escondido'], 'correta': 'Espalhar informação incorreta'}], 'reflexao': 'Qual decisão você tomaria nessa situação? Explique usando uma informação da história.'})
