HISTORIAS.append({'id': 'lei-v2-12-13-00', 'faixa_etaria': '12-13', 'colecao': 'Descobertas do cotidiano', 'tema': 'Cotidiano e escolhas', 'titulo': 'A ponte de papel', 'nivel': 'intermediario', 'nivel_numerico': 2, 'vocabulario': [], 'paginas': ['A turma precisava construir uma ponte para um carrinho. A primeira ponte dobrou no meio.', 'Nina sugeriu dobrar o papel em forma de sanfona. A turma testou a ideia e a ponte suportou o carrinho.', 'A turma registrou os dois testes e concluiu que a forma do papel mudou sua resistência.'], 'perguntas': [{'id': 'lei-v2-12-13-00-q1', 'enunciado': 'O que aconteceu com a primeira ponte?', 'alternativas': ['Ela dobrou no meio', 'Um jogo na televisão', 'Uma festa na escola', 'Uma viagem de trem'], 'correta': 'Ela dobrou no meio'}, {'id': 'lei-v2-12-13-00-q2', 'enunciado': 'Qual mudança ajudou a ponte?', 'alternativas': ['Ignorar o problema', 'Mudar de assunto', 'Esperar sem fazer nada', 'Dobrar o papel em sanfona'], 'correta': 'Dobrar o papel em sanfona'}, {'id': 'lei-v2-12-13-00-q3', 'enunciado': 'Qual conclusão foi registrada?', 'alternativas': ['Todos esqueceram o assunto', 'O problema foi escondido', 'A forma do papel mudou sua resistência', 'Nada mudou'], 'correta': 'A forma do papel mudou sua resistência'}], 'reflexao': 'Qual decisão você tomaria nessa situação? Explique usando uma informação da história.'})
