HISTORIAS.append({'id': 'lei-v2-12-13-17', 'faixa_etaria': '12-13', 'colecao': 'Descobertas do cotidiano', 'tema': 'Cotidiano e escolhas', 'titulo': 'A caixa de sementes', 'nivel': 'intermediario', 'nivel_numerico': 2, 'vocabulario': [], 'paginas': ['Ana guardou sementes de plantas diferentes em saquinhos iguais. Depois não lembrava qual era cada uma.', 'Ela pediu ajuda para identificar as sementes e escreveu etiquetas com os nomes.', 'Na próxima coleta, etiquetou os saquinhos antes de guardar. Assim, evitou a mesma confusão.'], 'perguntas': [{'id': 'lei-v2-12-13-17-q1', 'enunciado': 'Qual foi o problema?', 'alternativas': ['Um jogo na televisão', 'Uma festa na escola', 'Uma viagem de trem', 'Ana não lembrava qual era cada semente'], 'correta': 'Ana não lembrava qual era cada semente'}, {'id': 'lei-v2-12-13-17-q2', 'enunciado': 'Como organizou os saquinhos?', 'alternativas': ['Mudar de assunto', 'Esperar sem fazer nada', 'Com etiquetas de nomes', 'Ignorar o problema'], 'correta': 'Com etiquetas de nomes'}, {'id': 'lei-v2-12-13-17-q3', 'enunciado': 'O que mudou na próxima coleta?', 'alternativas': ['O problema foi escondido', 'Etiquetou antes de guardar', 'Nada mudou', 'Todos esqueceram o assunto'], 'correta': 'Etiquetou antes de guardar'}], 'reflexao': 'Qual decisão você tomaria nessa situação? Explique usando uma informação da história.'})
HISTORIAS.append({'id': 'lei-v2-12-13-18', 'faixa_etaria': '12-13', 'colecao': 'Descobertas do cotidiano', 'tema': 'Cotidiano e escolhas', 'titulo': 'A notícia conferida', 'nivel': 'intermediario', 'nivel_numerico': 2, 'vocabulario': [], 'paginas': ['Ivo recebeu uma mensagem dizendo que não haveria aula. A mensagem não tinha data nem fonte.', 'Antes de compartilhar, consultou o comunicado oficial da escola. As aulas estavam mantidas.', 'Ivo explicou aos colegas o que encontrou. Conferir a fonte evitou espalhar uma informação incorreta.'], 'perguntas': [{'id': 'lei-v2-12-13-18-q1', 'enunciado': 'O que faltava na mensagem?', 'alternativas': ['Uma festa na escola', 'Uma viagem de trem', 'Data e fonte', 'Um jogo na televisão'], 'correta': 'Data e fonte'}, {'id': 'lei-v2-12-13-18-q2', 'enunciado': 'Onde Ivo conferiu?', 'alternativas': ['Esperar sem fazer nada', 'No comunicado oficial da escola', 'Ignorar o problema', 'Mudar de assunto'], 'correta': 'No comunicado oficial da escola'}, {'id': 'lei-v2-12-13-18-q3', 'enunciado': 'O que evitou ao conferir?', 'alternativas': ['Espalhar informação incorreta', 'Nada mudou', 'Todos esqueceram o assunto', 'O problema foi escondido'], 'correta': 'Espalhar informação incorreta'}], 'reflexao': 'Qual decisão você tomaria nessa situação? Explique usando uma informação da história.'})
HISTORIAS.append({'id': 'lei-v2-12-13-19', 'faixa_etaria': '12-13', 'colecao': 'Descobertas do cotidiano', 'tema': 'Cotidiano e escolhas', 'titulo': 'O peso da mochila', 'nivel': 'intermediario', 'nivel_numerico': 2, 'vocabulario': [], 'paginas': ['Sofia carregava livros de todas as matérias diariamente. A mochila ficava pesada.', 'Ela consultou o horário e separou os materiais necessários para o dia seguinte.', 'A mochila ficou mais leve sem faltar material. Planejar ajudou a levar apenas o necessário.'], 'perguntas': [{'id': 'lei-v2-12-13-19-q1', 'enunciado': 'Por que a mochila ficava pesada?', 'alternativas': ['Uma viagem de trem', 'Levava livros de todas as matérias', 'Um jogo na televisão', 'Uma festa na escola'], 'correta': 'Levava livros de todas as matérias'}, {'id': 'lei-v2-12-13-19-q2', 'enunciado': 'O que Sofia consultou?', 'alternativas': ['O horário', 'Ignorar o problema', 'Mudar de assunto', 'Esperar sem fazer nada'], 'correta': 'O horário'}, {'id': 'lei-v2-12-13-19-q3', 'enunciado': 'Qual foi o resultado?', 'alternativas': ['Nada mudou', 'Todos esqueceram o assunto', 'O problema foi escondido', 'A mochila ficou mais leve'], 'correta': 'A mochila ficou mais leve'}], 'reflexao': 'Qual decisão você tomaria nessa situação? Explique usando uma informação da história.'})



