HISTORIAS.append({'id': 'lei-v3-00', 'faixa_etaria': '9-11', 'versao': 3, 'colecao': 'Histórias para pensar', 'tema': 'O campeonato que mudou de regra', 'titulo': 'O campeonato que mudou de regra', 'nivel': 'intermediario', 'nivel_numerico': 3, 'vocabulario': ['equipe', 'posições', 'oportunidades', 'treinos'], 'paginas': ['Na primeira semana do campeonato, a equipe de Júlia ganhou todas as partidas. Mesmo assim, ela percebeu que dois colegas quase nunca recebiam a bola. Quando um deles pediu para jogar em outra posição, o capitão respondeu que mudar poderia atrapalhar as vitórias. Júlia ficou em dúvida: também queria vencer, mas não achava justo chamar aquilo de trabalho em equipe.', 'Na reunião seguinte, propôs um treino com posições alternadas. O capitão aceitou experimentar durante vinte minutos, sem prometer mudanças no campeonato. No início houve passes errados. Depois, um dos colegas encontrou um espaço que ninguém havia percebido e ajudou a marcar um gol.', 'A experiência não demonstrou que qualquer mudança daria certo. Mostrou, porém, que os jogadores precisavam de oportunidades para revelar o que sabiam. A equipe decidiu alternar posições nos treinos e avaliar os resultados antes de escolher a formação da próxima partida.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'resumo', 'titulo': 'Reconstrua a ideia principal', 'instrucao': 'Apresente o tema e as informações essenciais. Explique como as ideias ou acontecimentos se relacionam, usando suas palavras.', 'minimo_palavras': 40, 'palavras_contexto': ['equipe', 'posições', 'oportunidades', 'treinos']}, 'perguntas': [{'id': 'lei-v3-00-q1', 'enunciado': 'Por que Júlia propôs alternar as posições?', 'correta': 'Dois colegas quase nunca recebiam a bola', 'alternativas': ['Porque a equipe perdia todas as partidas', 'Porque queria encerrar o campeonato', 'Porque as regras proibiam passes', 'Dois colegas quase nunca recebiam a bola']}, {'id': 'lei-v3-00-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Os colegas precisavam de oportunidades para mostrar suas habilidades', 'alternativas': ['O gol demonstrou que os dois colegas já eram os melhores jogadores da equipe.', 'A experiência provou que alternar posições garante a vitória em qualquer partida.', 'Como houve passes errados, os jogadores deveriam permanecer sempre nas posições antigas.', 'Os colegas precisavam de oportunidades para mostrar suas habilidades']}, {'id': 'lei-v3-00-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'Um colega encontrou um espaço e ajudou a marcar um gol', 'alternativas': ['Os colegas passaram vinte minutos sem errar passes durante a experiência.', 'A equipe perdeu as partidas iniciais depois que os dois colegas receberam a bola.', 'O capitão substituiu definitivamente a formação antes de realizar o treino.', 'Um colega encontrou um espaço e ajudou a marcar um gol']}]})
HISTORIAS.append({'id': 'lei-v3-01', 'faixa_etaria': '9-11', 'versao': 3, 'colecao': 'Histórias para pensar', 'tema': 'O mapa que não mostrava tudo', 'titulo': 'O mapa que não mostrava tudo', 'nivel': 'intermediario', 'nivel_numerico': 3, 'vocabulario': ['mapa', 'caminho', 'calçada', 'segurança'], 'paginas': ['Para chegar à nova biblioteca, Miguel escolheu no mapa o caminho mais curto. Sua avó pediu que observasse também as calçadas. Ele respondeu que o trajeto menor parecia obviamente melhor e anotou apenas a distância. No sábado, os dois saíram juntos para conhecer o lugar.', 'No caminho escolhido havia uma calçada interrompida por uma obra. Para continuar, precisariam fazer um desvio. A avó mostrou outra rua, um pouco mais longa, mas com calçada contínua e travessia sinalizada. Miguel refez a conta e descobriu que a diferença era de poucos minutos.', 'Ao voltar, acrescentou ao mapa informações sobre as travessias e a obra. Percebeu que o desenho não estava errado: apenas respondia a uma pergunta diferente. Indicava a distância, mas não avaliava todas as condições da caminhada. Na visita seguinte, escolheu o trajeto considerando distância e segurança. Decidiu ainda conferir se a obra já tinha terminado, pois uma informação útil também pode ficar desatualizada.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'opiniao', 'titulo': 'Defenda uma posição', 'instrucao': 'Defenda uma posição sobre a situação ou a ideia principal da leitura. Apresente duas razões e uma informação concreta do texto. Considere também uma possível objeção.', 'minimo_palavras': 40, 'palavras_contexto': ['mapa', 'caminho', 'calçada', 'segurança']}, 'perguntas': [{'id': 'lei-v3-01-q1', 'enunciado': 'Por que o caminho mais curto deixou de ser a melhor escolha?', 'correta': 'O caminho mais curto tinha uma calçada interrompida', 'alternativas': ['Porque a avó não queria visitar a biblioteca', 'Porque a biblioteca mudou de endereço', 'O caminho mais curto tinha uma calçada interrompida', 'Porque o mapa proibia a caminhada']}, {'id': 'lei-v3-01-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'O melhor caminho depende da distância e das condições da caminhada', 'alternativas': ['O melhor caminho depende da distância e das condições da caminhada', 'O desvio provou que o mapa estava errado ao indicar qual trajeto tinha menor distância.', 'O caminho mais curto é também o mais seguro, desde que esteja indicado no mapa.', 'Um mapa com obras e travessias pode ser usado sem novas verificações nas visitas seguintes.']}, {'id': 'lei-v3-01-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'A outra rua tinha calçada contínua e travessia sinalizada', 'alternativas': ['A avó recomendou a outra rua porque ela encurtava a distância até a biblioteca.', 'A obra já havia terminado quando Miguel escolheu o primeiro caminho.', 'Miguel descobriu que as duas ruas tinham a mesma distância e as mesmas travessias.', 'A outra rua tinha calçada contínua e travessia sinalizada']}]})
HISTORIAS.append({'id': 'lei-v3-02', 'faixa_etaria': '9-11', 'versao': 3, 'colecao': 'Histórias para pensar', 'tema': 'O sumiço das folhas verdes', 'titulo': 'O sumiço das folhas verdes', 'nivel': 'intermediario', 'nivel_numerico': 3, 'vocabulario': ['folhas', 'hipótese', 'observações', 'evidências'], 'paginas': ['As folhas da horta da escola apareceram furadas. Paulo viu uma lagarta perto de um vaso e afirmou que ela era responsável por todos os danos. Sua colega Elisa perguntou como ele poderia saber se havia observado apenas uma planta. Ele achou a pergunta exagerada, mas concordou em investigar antes de retirar os animais.', 'Durante três manhãs, a dupla anotou quais folhas tinham novos furos. Também fotografou os vasos e verificou a terra. Algumas plantas apresentavam danos recentes mesmo quando não havia lagartas visíveis. Em um dos vasos, encontraram pequenos caracóis escondidos sob uma tábua.', "A professora explicou que observações incompletas podem sustentar explicações apressadas. Isso não tornava a primeira hipótese inútil; significava que ela precisava ser confrontada com outras informações. A turma organizou um acompanhamento da horta e pediu orientação sobre o manejo adequado. Paulo passou a escrever 'pode ser' em suas primeiras anotações e guardou a certeza para conclusões apoiadas em mais evidências."], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'continuacao', 'titulo': 'Crie uma continuação coerente', 'instrucao': 'Imagine uma nova etapa para essa situação. Preserve os fatos e participantes do texto, apresente um novo problema e explique como ele se desenvolve.', 'minimo_palavras': 40, 'palavras_contexto': ['folhas', 'hipótese', 'observações', 'evidências']}, 'perguntas': [{'id': 'lei-v3-02-q1', 'enunciado': 'O que tornou a conclusão inicial de Paulo precipitada?', 'correta': 'Paulo tinha observado apenas uma planta', 'alternativas': ['A turma sabia que folhas nunca apresentam furos', 'A professora já tinha identificado todos os animais', 'Paulo tinha observado apenas uma planta', 'Ele havia examinado todos os vasos por um mês']}, {'id': 'lei-v3-02-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Uma hipótese precisa ser verificada antes de virar conclusão', 'alternativas': ['Uma hipótese precisa ser verificada antes de virar conclusão', 'Investigar várias plantas só seria necessário se a primeira hipótese fosse comprovadamente falsa.', 'A descoberta dos caracóis demonstrou que nenhuma lagarta danificava as plantas.', 'Encontrar uma lagarta foi suficiente para identificar a causa de todos os furos da horta.']}, {'id': 'lei-v3-02-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'Encontraram caracóis em outro vaso com danos recentes', 'alternativas': ['O acompanhamento confirmou uma única causa para todos os danos dos diferentes vasos.', 'Os registros mostraram que os furos desapareceram antes do início das observações.', 'Encontraram caracóis em outro vaso com danos recentes', 'A dupla encontrou lagartas visíveis em todas as plantas que apresentavam danos recentes.']}]})
HISTORIAS.append({'id': 'lei-v3-03', 'faixa_etaria': '9-11', 'versao': 3, 'colecao': 'Histórias para pensar', 'tema': 'A troca de livros', 'titulo': 'A troca de livros', 'nivel': 'intermediario', 'nivel_numerico': 3, 'vocabulario': ['livros', 'troca', 'regras', 'leitura'], 'paginas': ['A turma de Sara organizou uma feira de troca de livros. A regra inicial era simples: cada estudante entregaria um livro e receberia outro. No dia da preparação, descobriram exemplares com páginas faltando e livros quase novos. Alguns colegas sugeriram separar os títulos pelo preço original. Outros disseram que uma história podia ser valiosa mesmo em um exemplar antigo.', 'Sara propôs distinguir preço e condições de leitura. Com ajuda da professora, a turma conferiu se os livros estavam completos e se o texto podia ser lido com conforto. Os exemplares danificados foram para uma mesa de reparos. Os demais receberam uma ficha com o tema e uma breve recomendação escrita por quem os trouxe.', 'A solução não eliminou todas as preferências: alguns títulos continuaram mais procurados. Por isso, a escolha aconteceu em rodadas com ordem alternada. Ao final, a turma registrou o que funcionou e o que deveria mudar na próxima feira. Descobriu que uma regra simples pode precisar de ajustes para tratar situações diferentes com cuidado.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'comparacao', 'titulo': 'Compare as escolhas', 'instrucao': 'Compare duas escolhas, interpretações ou momentos apresentados na leitura. Explique uma diferença, uma consequência e a informação que sustenta sua comparação.', 'minimo_palavras': 40, 'palavras_contexto': ['livros', 'troca', 'regras', 'leitura']}, 'perguntas': [{'id': 'lei-v3-03-q1', 'enunciado': 'Por que separar apenas pelo preço não resolvia a situação?', 'correta': 'Havia livros em condições muito diferentes', 'alternativas': ['Havia livros em condições muito diferentes', 'Porque todos os livros tinham exatamente o mesmo preço', 'Porque o preço identificava páginas faltando automaticamente', 'Porque ninguém queria participar da feira']}, {'id': 'lei-v3-03-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'A turma ajustou as regras considerando as condições e o acesso aos livros', 'alternativas': ['A turma resolveu a diferença de condições permitindo que os livros mais caros fossem escolhidos primeiro.', 'Classificar os livros pelo preço original tornou desnecessária a conferência das páginas.', 'A turma ajustou as regras considerando as condições e o acesso aos livros', 'Depois dos reparos, todos os livros passaram a despertar o mesmo interesse entre os estudantes.']}, {'id': 'lei-v3-03-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'Os livros danificados foram separados para reparos', 'alternativas': ['Os livros com páginas faltando foram distribuídos primeiro, antes de qualquer reparo.', 'Os livros danificados foram separados para reparos', 'As fichas passaram a informar o preço original como único critério para permitir a troca.', 'A ordem das escolhas permaneceu igual em todas as rodadas, apesar dos títulos mais procurados.']}]})
HISTORIAS.append({'id': 'lei-v3-04', 'faixa_etaria': '9-11', 'versao': 3, 'colecao': 'Histórias para pensar', 'tema': 'O relógio da experiência', 'titulo': 'O relógio da experiência', 'nivel': 'intermediario', 'nivel_numerico': 3, 'vocabulario': ['teste', 'panos', 'comparação', 'condições'], 'paginas': ['Bruno queria descobrir em qual lugar uma roupa secava mais depressa. Colocou uma camiseta no sol e uma toalha na sombra. Duas horas depois, a camiseta estava seca. Ele escreveu que o sol sempre secava qualquer tecido em menos tempo.', 'Ao ler a anotação, sua irmã perguntou se a diferença poderia ter relação com o tamanho e a espessura das peças. Bruno percebeu que havia mudado duas coisas ao mesmo tempo: o lugar e o tipo de tecido. Para comparar melhor, os dois usaram panos iguais, molhados com quantidades semelhantes de água. Também anotaram o horário e observaram se havia vento.', 'O segundo teste voltou a mostrar secagem mais rápida ao sol naquele dia. A conclusão, porém, ficou mais cuidadosa: nas condições observadas, um pano igual secou mais depressa no local ensolarado. Bruno não ficou decepcionado por escrever uma conclusão menor. Entendeu que uma afirmação limitada por boas observações pode ser mais útil do que uma promessa enorme que o teste não conseguiu demonstrar.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'resumo', 'titulo': 'Reconstrua a ideia principal', 'instrucao': 'Apresente o tema e as informações essenciais. Explique como as ideias ou acontecimentos se relacionam, usando suas palavras.', 'minimo_palavras': 40, 'palavras_contexto': ['teste', 'panos', 'comparação', 'condições']}, 'perguntas': [{'id': 'lei-v3-04-q1', 'enunciado': 'Qual foi o principal problema do primeiro teste?', 'correta': 'As peças iniciais tinham tipos e espessuras diferentes', 'alternativas': ['A sombra não existia naquele dia', 'As duas peças eram idênticas em todas as condições', 'Bruno não sabia ler o relógio', 'As peças iniciais tinham tipos e espessuras diferentes']}, {'id': 'lei-v3-04-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Uma comparação precisa controlar outras diferenças que afetam o resultado', 'alternativas': ['O segundo teste provou que o vento nunca interfere na secagem de nenhum tipo de tecido.', 'Uma comparação precisa controlar outras diferenças que afetam o resultado', 'A conclusão mais cuidadosa indica que o sol não teve relação com a secagem observada naquele dia.', 'O primeiro teste já isolava o efeito do sol, pois as duas peças ficaram molhadas pelo mesmo tempo.']}, {'id': 'lei-v3-04-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'No segundo teste usaram panos iguais', 'alternativas': ['A irmã confirmou que a camiseta e a toalha iniciais tinham a mesma espessura e tamanho.', 'No segundo teste usaram panos iguais', 'No segundo teste, os dois trocaram os horários de observação e mantiveram tecidos diferentes.', 'Bruno repetiu a experiência sem registrar a quantidade de água colocada em cada pano.']}]})
HISTORIAS.append({'id': 'lei-v3-05', 'faixa_etaria': '9-11', 'versao': 3, 'colecao': 'Histórias para pensar', 'tema': 'O bilhete sem nome', 'titulo': 'O bilhete sem nome', 'nivel': 'intermediario', 'nivel_numerico': 3, 'vocabulario': ['bilhete', 'leitura', 'reclamação', 'acordo'], 'paginas': ['No mural da sala apareceu um bilhete reclamando do barulho durante a leitura. O texto não tinha assinatura. Alguns estudantes disseram que só poderiam discutir a reclamação depois de descobrir quem havia escrito. Lara discordou: o nome poderia ajudar a conversar, mas não dizia se o problema existia.', 'A professora sugeriu observar a sala em dois momentos diferentes. Durante a leitura silenciosa, três grupos continuaram falando. Em uma atividade coletiva, o mesmo volume de conversa fazia parte da tarefa. A turma percebeu que chamar qualquer conversa de bagunça também seria uma conclusão injusta.', 'Na assembleia, combinaram sinais para distinguir trabalho em grupo e leitura individual. Também criaram uma caixa para sugestões, com possibilidade de identificação voluntária. Lara escreveu no registro que ouvir uma reclamação não significa aceitá-la automaticamente. Significa examinar o que foi relatado, buscar informações e conversar sobre uma solução. O bilhete continuou sem autor conhecido, mas levou a um acordo que todos puderam avaliar.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'opiniao', 'titulo': 'Defenda uma posição', 'instrucao': 'Defenda uma posição sobre a situação ou a ideia principal da leitura. Apresente duas razões e uma informação concreta do texto. Considere também uma possível objeção.', 'minimo_palavras': 40, 'palavras_contexto': ['bilhete', 'leitura', 'reclamação', 'acordo']}, 'perguntas': [{'id': 'lei-v3-05-q1', 'enunciado': 'Por que descobrir o autor não era suficiente para avaliar o bilhete?', 'correta': 'Havia conversa durante a leitura silenciosa', 'alternativas': ['Havia conversa durante a leitura silenciosa', 'Porque o mural não pertencia à escola', 'Porque a professora proibiu qualquer observação', 'Porque o nome provaria automaticamente que a reclamação era falsa']}, {'id': 'lei-v3-05-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Uma reclamação pode ser examinada mesmo quando seu autor não é conhecido', 'alternativas': ['Uma reclamação pode ser examinada mesmo quando seu autor não é conhecido', 'O acordo exigiu o mesmo silêncio tanto nas atividades coletivas quanto na leitura individual.', 'Criar uma caixa de sugestões comprovou que toda conversa em sala atrapalhava a aprendizagem.', 'A ausência de assinatura tornou a reclamação falsa, mesmo após a observação da sala.']}, {'id': 'lei-v3-05-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'Observaram comportamentos diferentes conforme a atividade', 'alternativas': ['Observaram comportamentos diferentes conforme a atividade', 'A professora analisou apenas o volume da conversa coletiva e dispensou observar a leitura individual.', 'A turma identificou o autor antes de começar a investigar o barulho relatado no bilhete.', 'Os grupos mantiveram o mesmo comportamento em silêncio durante as duas atividades observadas.']}]})
HISTORIAS.append({'id': 'lei-v3-06', 'faixa_etaria': '9-11', 'versao': 3, 'colecao': 'Histórias para pensar', 'tema': 'A encomenda e o prazo', 'titulo': 'A encomenda e o prazo', 'nivel': 'intermediario', 'nivel_numerico': 4, 'vocabulario': ['prazo', 'etapas', 'estimativa', 'entrega'], 'paginas': ['A classe de Tainá prometeu produzir quarenta marcadores de página para uma feira. No primeiro encontro, fez dez em meia hora. Animada, Tainá calculou que terminaria tudo em duas horas. Esqueceu, porém, que o primeiro grupo usava materiais já recortados por uma funcionária.', 'Na semana seguinte, os estudantes precisaram medir, recortar, colar e esperar a cola secar. A produção foi mais lenta. Alguns colegas quiseram acelerar sem conferir as medidas. Outros sugeriram diminuir a quantidade prometida sem avisar a organização. Tainá propôs registrar o tempo de cada etapa e conversar sobre o prazo antes de decidir.', 'A turma dividiu as tarefas e descobriu que poderia preparar os recortes enquanto outros montavam as peças. Ainda assim, seria necessário mais um encontro. Tainá enviou um aviso explicando a situação e combinou uma entrega parcial. A organização aceitou porque recebeu a informação com antecedência. No relatório, a classe concluiu que uma estimativa depende das condições em que os dados foram obtidos. Planejar também inclui comunicar mudanças, e não apenas fazer uma conta.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'continuacao', 'titulo': 'Crie uma continuação coerente', 'instrucao': 'Imagine uma nova etapa para essa situação. Preserve os fatos e participantes do texto, apresente um novo problema e explique como ele se desenvolve.', 'minimo_palavras': 40, 'palavras_contexto': ['prazo', 'etapas', 'estimativa', 'entrega']}, 'perguntas': [{'id': 'lei-v3-06-q1', 'enunciado': 'O que tornou a primeira previsão de Tainá incompleta?', 'correta': 'Os materiais do primeiro encontro já estavam recortados', 'alternativas': ['O grupo não tinha produzido nenhuma peça', 'A feira não havia solicitado marcadores', 'Ela incluiu todas as etapas e imprevistos possíveis', 'Os materiais do primeiro encontro já estavam recortados']}, {'id': 'lei-v3-06-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Uma estimativa precisa considerar todas as etapas e comunicar mudanças', 'alternativas': ['O ritmo inicial podia ser aplicado a todos os encontros, pois o produto final era o mesmo.', 'A divisão de tarefas garantiu o prazo original sem precisar comunicar a organização.', 'A solução escolhida foi entregar menos marcadores do que o combinado sem alterar o prazo informado.', 'Uma estimativa precisa considerar todas as etapas e comunicar mudanças']}, {'id': 'lei-v3-06-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'A turma mediu o tempo das etapas e negociou uma entrega parcial', 'alternativas': ['A turma confirmou que medir e recortar consumiam o mesmo tempo que receber materiais prontos.', 'A turma mediu o tempo das etapas e negociou uma entrega parcial', 'A organização rejeitou o aviso antecipado e exigiu que toda a entrega fosse cancelada.', 'O grupo deixou de medir as peças para manter a velocidade do primeiro encontro.']}]})
HISTORIAS.append({'id': 'lei-v3-07', 'faixa_etaria': '9-11', 'versao': 3, 'colecao': 'Histórias para pensar', 'tema': 'Quem escolhe a notícia', 'titulo': 'Quem escolhe a notícia', 'nivel': 'intermediario', 'nivel_numerico': 4, 'vocabulario': ['jornal', 'consulta', 'critérios', 'leitores'], 'paginas': ["O jornal da escola recebeu três sugestões para a capa: a vitória do time, o início de uma campanha de doações e uma entrevista com a equipe da limpeza. Henrique defendia o esporte porque acreditava que todos gostavam de futebol. Luísa perguntou quem estava incluído nesse 'todos'.", 'A equipe fez uma pequena consulta em quatro turmas. O esporte recebeu muitos votos, mas também apareceram pedidos por notícias de projetos e do cotidiano escolar. Os estudantes perceberam que a consulta não representava automaticamente a escola inteira, pois algumas turmas não tinham participado.', 'Decidiram publicar as três matérias, com uma chamada principal sobre a campanha, que começaria naquela semana. Explicaram que a urgência do assunto influenciou a escolha. Reservaram o destaque esportivo para uma edição seguinte e ampliaram os canais de sugestões. Henrique continuou preferindo o futebol, mas reconheceu que sua preferência não precisava orientar todas as capas. A equipe terminou o encontro com uma tarefa nova: escrever os critérios usados nas decisões para que os leitores pudessem questioná-los e sugerir melhorias.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'comparacao', 'titulo': 'Compare as escolhas', 'instrucao': 'Compare duas escolhas, interpretações ou momentos apresentados na leitura. Explique uma diferença, uma consequência e a informação que sustenta sua comparação.', 'minimo_palavras': 40, 'palavras_contexto': ['jornal', 'consulta', 'critérios', 'leitores']}, 'perguntas': [{'id': 'lei-v3-07-q1', 'enunciado': 'Por que a consulta não permitia afirmar o que toda a escola queria?', 'correta': 'A preferência de Henrique não representava necessariamente toda a escola', 'alternativas': ['Porque nenhuma turma respondeu', 'Porque consultar pessoas impede qualquer decisão', 'Porque todos os estudantes tinham participado com as mesmas respostas', 'A preferência de Henrique não representava necessariamente toda a escola']}, {'id': 'lei-v3-07-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Escolhas editoriais precisam de critérios e atenção a diferentes leitores', 'alternativas': ['Escolhas editoriais precisam de critérios e atenção a diferentes leitores', 'A matéria esportiva recebeu prioridade imediata porque era o assunto mais urgente daquela semana.', 'A consulta mostrou que a preferência pessoal de Henrique deveria orientar todas as próximas capas.', 'Os votos de quatro turmas demonstraram que todos os estudantes preferiam futebol na capa.']}, {'id': 'lei-v3-07-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'A consulta encontrou interesses diferentes e participação limitada', 'alternativas': ['A consulta encontrou interesses diferentes e participação limitada', 'Todas as turmas da escola participaram da consulta e escolheram a mesma matéria principal.', 'A equipe selecionou a capa sem considerar o início da campanha de doações naquela semana.', 'O jornal excluiu as matérias menos votadas e publicou apenas o conteúdo esportivo.']}]})
HISTORIAS.append({'id': 'lei-v3-08', 'faixa_etaria': '9-11', 'versao': 3, 'colecao': 'Histórias para pensar', 'tema': 'O banco de sementes', 'titulo': 'O banco de sementes', 'nivel': 'intermediario', 'nivel_numerico': 4, 'vocabulario': ['sementes', 'lotes', 'registros', 'germinação'], 'paginas': ['Na feira de ciências, Marina recebeu sementes de três hortas. Os envelopes tinham nomes de plantas, mas não informavam quando as sementes haviam sido colhidas. Ela pretendia misturar todas em uma caixa para economizar espaço. Seu colega André sugeriu manter os lotes separados até observar a germinação.', 'A dupla colocou quantidades iguais de cada lote em recipientes identificados. Registrou a água usada, o lugar e os dias de observação. Em dois lotes surgiram várias mudas; no terceiro, poucas sementes germinaram. André quis descartar o terceiro lote imediatamente, mas Marina lembrou que um único teste não explicava a causa do resultado.', 'Eles repetiram a experiência com outras sementes e consultaram quem as havia doado. Descobriram que um envelope tinha ficado em um lugar úmido antes da entrega. Essa informação ajudou a formular uma explicação, sem provar que era a única causa possível. O banco de sementes ganhou etiquetas com origem, data disponível e condições de armazenamento. A caixa ocupou mais espaço do que Marina imaginava, mas os registros tornaram seu conteúdo muito mais útil para os próximos plantios.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'resumo', 'titulo': 'Reconstrua a ideia principal', 'instrucao': 'Apresente o tema e as informações essenciais. Explique como as ideias ou acontecimentos se relacionam, usando suas palavras.', 'minimo_palavras': 40, 'palavras_contexto': ['sementes', 'lotes', 'registros', 'germinação']}, 'perguntas': [{'id': 'lei-v3-08-q1', 'enunciado': 'Qual informação teria sido perdida ao misturar os lotes?', 'correta': 'Misturar as sementes apagaria diferenças de origem e armazenamento', 'alternativas': ['Misturar as sementes apagaria diferenças de origem e armazenamento', 'A quantidade de mesas na feira', 'O nome da escola escrito no cartaz', 'A cor da caixa onde todos seriam guardados']}, {'id': 'lei-v3-08-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Manter lotes identificados permite comparar resultados e investigar causas', 'alternativas': ['Manter lotes identificados permite comparar resultados e investigar causas', 'Misturar os lotes permitiria identificar melhor qual horta havia fornecido as sementes que não germinaram.', 'Como dois lotes germinaram bem, a origem das sementes deixou de ser útil nos próximos plantios.', 'A germinação menor comprovou que a umidade anterior era a única causa do resultado do terceiro lote.']}, {'id': 'lei-v3-08-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'Os lotes apresentaram germinação diferente', 'alternativas': ['Marina descartou o terceiro lote sem repetir a experiência ou consultar os doadores.', 'As sementes foram misturadas antes do teste e só depois receberam etiquetas de origem.', 'Os lotes apresentaram germinação diferente', 'Os três lotes apresentaram exatamente a mesma germinação nas primeiras observações.']}]})
HISTORIAS.append({'id': 'lei-v3-09', 'faixa_etaria': '9-11', 'versao': 3, 'colecao': 'Histórias para pensar', 'tema': 'Uma praça para usos diferentes', 'titulo': 'Uma praça para usos diferentes', 'nivel': 'intermediario', 'nivel_numerico': 4, 'vocabulario': ['praça', 'usos', 'alternativas', 'moradores'], 'paginas': ['No bairro de Felipe, um grupo queria transformar parte da praça em quadra. Outro defendia conservar o espaço de sombra usado por idosos e famílias. Na primeira reunião, cada lado falou como se existisse apenas uma escolha: construir a quadra ou impedir qualquer mudança.', 'Felipe ajudou a desenhar um mapa dos usos atuais. Durante a semana, os moradores anotaram horários, circulação e áreas ocupadas. A observação mostrou que o terreno mais ensolarado ficava vazio em vários períodos, enquanto a sombra era muito procurada depois do almoço. Também havia uma passagem usada por pessoas com dificuldade para caminhar.', 'Com essas informações, surgiram propostas menores: marcar uma área de jogos sem retirar árvores e reorganizar alguns bancos. Nenhuma solução atendia perfeitamente a todos, e seria necessário consultar os responsáveis pelo espaço. Mesmo assim, a conversa mudou. Os moradores passaram a discutir consequências concretas em vez de defender somente suas primeiras ideias. Felipe percebeu que ouvir necessidades diferentes não garante um acordo imediato, mas pode revelar alternativas que uma disputa entre dois lados esconde.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'opiniao', 'titulo': 'Defenda uma posição', 'instrucao': 'Defenda uma posição sobre a situação ou a ideia principal da leitura. Apresente duas razões e uma informação concreta do texto. Considere também uma possível objeção.', 'minimo_palavras': 40, 'palavras_contexto': ['praça', 'usos', 'alternativas', 'moradores']}, 'perguntas': [{'id': 'lei-v3-09-q1', 'enunciado': 'Como o levantamento mudou a discussão?', 'correta': 'Os moradores tinham necessidades diferentes para a praça', 'alternativas': ['Demonstrou que apenas um morador podia decidir', 'Provou que ninguém utilizava a praça', 'Eliminou a necessidade de consultar os responsáveis', 'Os moradores tinham necessidades diferentes para a praça']}, {'id': 'lei-v3-09-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Conhecer diferentes usos do espaço pode revelar alternativas de projeto', 'alternativas': ['O mapa confirmou que conservar a sombra exigia impedir qualquer alteração em outra parte da praça.', 'Conhecer diferentes usos do espaço pode revelar alternativas de projeto', 'As novas propostas dispensaram a consulta aos responsáveis por já atenderem perfeitamente a todos.', 'O levantamento provou que toda a praça podia virar quadra porque nenhuma área era usada regularmente.']}, {'id': 'lei-v3-09-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'O mapa mostrou áreas e horários de uso diferentes', 'alternativas': ['O terreno mais ensolarado era ocupado continuamente, sem períodos disponíveis para jogos.', 'Os registros indicaram que a sombra permanecia vazia justamente no período depois do almoço.', 'O mapa mostrou áreas e horários de uso diferentes', 'O grupo decidiu retirar as árvores antes de levantar a circulação de pessoas no local.']}]})
HISTORIAS.append({'id': 'lei-v3-10', 'faixa_etaria': '9-11', 'versao': 3, 'colecao': 'Histórias para pensar', 'tema': 'A fotografia fora de contexto', 'titulo': 'A fotografia fora de contexto', 'nivel': 'intermediario', 'nivel_numerico': 4, 'vocabulario': ['fotografia', 'legenda', 'contexto', 'doações'], 'paginas': ['Uma fotografia mostrava caixas espalhadas no pátio da escola. Na legenda de uma mensagem, alguém escreveu que os estudantes haviam abandonado o material de uma campanha. Rafael quase encaminhou a imagem para o grupo da família, mas reconheceu um cartaz ao fundo e resolveu perguntar sobre a data.', 'Uma funcionária explicou que a foto tinha sido feita durante a separação das doações. As caixas ficaram no pátio por alguns minutos antes de serem levadas ao depósito. Havia outras fotografias da mesma manhã mostrando os materiais organizados. Rafael percebeu que a imagem era verdadeira, mas a legenda levava a uma interpretação enganosa.', 'Ele escreveu uma resposta com a data e a explicação recebida, sem acusar quem enviou a mensagem de ter inventado tudo de propósito. Também pediu que conferissem a informação antes de compartilhar. A experiência mostrou que verificar uma imagem não se resume a descobrir se ela foi alterada. É preciso investigar quando foi feita, o que aconteceu antes e depois e quais informações ficaram fora do enquadramento.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'continuacao', 'titulo': 'Crie uma continuação coerente', 'instrucao': 'Imagine uma nova etapa para essa situação. Preserve os fatos e participantes do texto, apresente um novo problema e explique como ele se desenvolve.', 'minimo_palavras': 40, 'palavras_contexto': ['fotografia', 'legenda', 'contexto', 'doações']}, 'perguntas': [{'id': 'lei-v3-10-q1', 'enunciado': 'O que havia de enganoso na mensagem?', 'correta': 'A fotografia mostrava apenas um momento da organização das doações', 'alternativas': ['A escola não tinha pátio', 'A fotografia mostrava apenas um momento da organização das doações', 'Todas as caixas eram desenhos', 'A fotografia nunca havia sido feita']}, {'id': 'lei-v3-10-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Uma imagem verdadeira pode receber uma legenda que distorce seu contexto', 'alternativas': ['O material organizado em outra imagem demonstra que as caixas nunca chegaram a ficar no pátio.', 'As fotografias adicionais provaram que quem encaminhou a primeira mensagem pretendia enganar as famílias.', 'A confirmação de que a foto era verdadeira demonstrou também que a legenda estava correta.', 'Uma imagem verdadeira pode receber uma legenda que distorce seu contexto']}, {'id': 'lei-v3-10-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'Outras fotos mostravam os materiais organizados', 'alternativas': ['Rafael descobriu que a foto tinha sido feita em outra escola, sem relação com a campanha.', 'Outras fotos mostravam os materiais organizados', 'Uma funcionária confirmou que a fotografia registrava o abandono definitivo das doações.', 'A data e a sequência mostraram que o material continuou espalhado após o encerramento da campanha.']}]})
HISTORIAS.append({'id': 'lei-v3-11', 'faixa_etaria': '9-11', 'versao': 3, 'colecao': 'Histórias para pensar', 'tema': 'O ingresso coletivo', 'titulo': 'O ingresso coletivo', 'nivel': 'intermediario', 'nivel_numerico': 4, 'vocabulario': ['desconto', 'custos', 'condições', 'orçamento'], 'paginas': ['A turma de Beatriz juntou dinheiro para visitar um museu. A promoção anunciava desconto para grupos, e a conta inicial parecia caber no orçamento. Quando a professora pediu os detalhes, descobriram que o desconto valia apenas em certos dias e não incluía o transporte.', 'Alguns estudantes sugeriram cancelar a visita. Outros queriam usar toda a reserva e decidir depois como pagar o ônibus. Beatriz propôs escrever uma lista de custos obrigatórios e consultar mais de uma alternativa. A turma comparou datas, transporte e atividades gratuitas oferecidas pelo museu.', 'Uma nova data permitiria usar o desconto e dividir o ônibus com outra turma, desde que houvesse autorização e lugares suficientes. O grupo conferiu essas condições antes de apresentar a proposta às famílias. A visita continuou possível, mas o preço destacado no anúncio deixou de ser tratado como o custo total. Beatriz registrou que uma boa oferta só pode ser avaliada depois que suas condições são compreendidas. Também separou uma pequena reserva para despesas previstas, em vez de contar com um dinheiro que ainda não existia.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'comparacao', 'titulo': 'Compare as escolhas', 'instrucao': 'Compare duas escolhas, interpretações ou momentos apresentados na leitura. Explique uma diferença, uma consequência e a informação que sustenta sua comparação.', 'minimo_palavras': 40, 'palavras_contexto': ['desconto', 'custos', 'condições', 'orçamento']}, 'perguntas': [{'id': 'lei-v3-11-q1', 'enunciado': 'Por que o valor anunciado não bastava para planejar a visita?', 'correta': 'O anúncio não incluía transporte e restringia os dias do desconto', 'alternativas': ['Porque todos os custos já estavam incluídos', 'Porque o museu não aceitava nenhum visitante', 'O anúncio não incluía transporte e restringia os dias do desconto', 'Porque comparar preços aumentaria obrigatoriamente o gasto']}, {'id': 'lei-v3-11-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Avaliar uma oferta exige considerar suas condições e o custo total', 'alternativas': ['Mudar a data permitiria dividir o ônibus sem precisar conferir lugares ou autorização.', 'Usar toda a reserva para os ingressos eliminaria o problema dos custos que ainda faltavam pagar.', 'O desconto do ingresso já representava o gasto completo da turma, qualquer que fosse o transporte.', 'Avaliar uma oferta exige considerar suas condições e o custo total']}, {'id': 'lei-v3-11-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'A turma comparou datas e alternativas de transporte', 'alternativas': ['A turma confirmou que o desconto estava disponível em qualquer dia de visita.', 'O museu informou que o preço promocional já incluía o ônibus de todas as turmas.', 'A turma comparou datas e alternativas de transporte', 'Beatriz propôs apresentar a divisão do ônibus às famílias antes de conferir suas condições.']}]})
HISTORIAS.append({'id': 'lei-v3-12', 'faixa_etaria': '12-13', 'versao': 3, 'colecao': 'Investigar e argumentar', 'tema': 'O algoritmo e a fila', 'titulo': 'O algoritmo e a fila', 'nivel': 'intermediario', 'nivel_numerico': 4, 'vocabulario': ['regra', 'turmas', 'acesso', 'critérios'], 'paginas': ['Uma escola criou uma planilha para distribuir horários da quadra. O sistema escolhia primeiro as turmas que enviavam o pedido mais cedo. Durante o primeiro mês, quase todos os melhores horários ficaram com os mesmos grupos. A equipe responsável afirmou que a regra era neutra, pois valia igualmente para todos.', 'Na avaliação, os representantes descobriram que algumas turmas podiam usar um computador no início do dia, enquanto outras só tinham acesso depois das aulas. A regra era igual no papel, mas as condições para participar eram diferentes. Trocar o nome de quem organizava a lista não resolveria essa diferença.', 'A escola testou uma combinação de rodízio e prioridade para grupos que tinham recebido menos horários. Publicou os critérios e abriu um período para reclamações. A nova versão também apresentou dificuldades: certas atividades precisavam de horários específicos. Por isso, a equipe manteve o acompanhamento e registrou as exceções.', 'O caso não mostrou que organizar por ordem de chegada é sempre injusto. Mostrou que uma decisão automática incorpora escolhas humanas. Avaliar o resultado exige perguntar quem consegue participar, quais necessidades foram consideradas e como uma regra pode ser contestada.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'resumo', 'titulo': 'Reconstrua a ideia principal', 'instrucao': 'Apresente o tema e as informações essenciais. Explique como as ideias ou acontecimentos se relacionam, usando suas palavras.', 'minimo_palavras': 55, 'palavras_contexto': ['regra', 'turmas', 'acesso', 'critérios']}, 'perguntas': [{'id': 'lei-v3-12-q1', 'enunciado': 'Por que aplicar a mesma regra não garantiu oportunidades equivalentes?', 'correta': 'As turmas tinham acesso ao computador em horários diferentes', 'alternativas': ['Porque todos tinham as mesmas condições de envio', 'Porque a quadra não tinha horários disponíveis', 'Porque a planilha sorteava números sem qualquer critério', 'As turmas tinham acesso ao computador em horários diferentes']}, {'id': 'lei-v3-12-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Uma regra automática pode reproduzir diferenças nas condições de participação', 'alternativas': ['Uma regra aplicada igualmente garante oportunidades equivalentes, mesmo com acesso diferente aos computadores.', 'Trocar quem organizava a lista seria suficiente para corrigir a diferença de acesso entre as turmas.', 'O rodízio resolveu todas as necessidades de horários e tornou desnecessário acompanhar exceções.', 'Uma regra automática pode reproduzir diferenças nas condições de participação']}, {'id': 'lei-v3-12-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'Os melhores horários ficaram repetidamente com os mesmos grupos', 'alternativas': ['O primeiro sistema reservava os melhores horários às turmas que os tinham recebido menos vezes.', 'O teste de rodízio mostrou que nenhuma atividade dependia de horários específicos.', 'Os melhores horários ficaram repetidamente com os mesmos grupos', 'As turmas tinham acesso ao computador no mesmo horário, mas a planilha ignorava alguns pedidos.']}]})
HISTORIAS.append({'id': 'lei-v3-13', 'faixa_etaria': '12-13', 'versao': 3, 'colecao': 'Investigar e argumentar', 'tema': 'A pesquisa que virou manchete', 'titulo': 'A pesquisa que virou manchete', 'nivel': 'intermediario', 'nivel_numerico': 4, 'vocabulario': ['pesquisa', 'participantes', 'pergunta', 'generalizar'], 'paginas': ['Um portal publicou que nove em cada dez adolescentes preferiam estudar com vídeos. A manchete parecia descrever toda uma geração. Ao abrir a reportagem, Camila descobriu que a pesquisa havia sido respondida por cem seguidores de um canal dedicado a aulas em vídeo.', 'O resultado podia informar algo sobre aquele público, mas não representava necessariamente estudantes que não acompanhavam o canal. Além disso, a pergunta oferecia apenas duas alternativas: vídeos ou livros. Não permitia escolher aulas presenciais, exercícios, combinações de recursos ou respostas diferentes conforme a matéria.', 'Na aula de produção textual, Camila apresentou duas versões de título. A primeira repetia a conclusão ampla. A segunda identificava o grupo consultado e evitava generalizar. Alguns colegas acharam a segunda menos chamativa; outros observaram que ela ajudava o leitor a interpretar o número.', 'A turma decidiu que o problema não estava em divulgar resultados numéricos. Estava em omitir informações necessárias para compreender seu alcance. No texto final, separou resultado e interpretação: noventa participantes escolheram vídeos naquela pergunta, mas seria preciso outro desenho de pesquisa para falar de todos os adolescentes. A precisão exigiu algumas palavras a mais e uma promessa bem menor.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'opiniao', 'titulo': 'Defenda uma posição', 'instrucao': 'Defenda uma posição sobre a situação ou a ideia principal da leitura. Apresente duas razões e uma informação concreta do texto. Considere também uma possível objeção.', 'minimo_palavras': 55, 'palavras_contexto': ['pesquisa', 'participantes', 'pergunta', 'generalizar']}, 'perguntas': [{'id': 'lei-v3-13-q1', 'enunciado': 'Que limite impede generalizar o resultado para todos os adolescentes?', 'correta': 'Os participantes eram seguidores de um canal de vídeos', 'alternativas': ['Os participantes eram seguidores de um canal de vídeos', 'Uma porcentagem nunca pode ser calculada', 'Cem respostas garantem a representação de qualquer população', 'Todo seguidor do canal tinha a mesma idade e rotina comprovadas']}, {'id': 'lei-v3-13-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'O alcance de uma pesquisa depende de quem respondeu e de como a pergunta foi feita', 'alternativas': ['Identificar o público consultado faria a porcentagem calculada perder sua validade para aqueles participantes.', 'O alcance de uma pesquisa depende de quem respondeu e de como a pergunta foi feita', 'Os noventa votos demonstravam a preferência por vídeo em todas as matérias e combinações de estudo.', 'O número de cem respostas assegurava a representação de todos os adolescentes, independentemente da seleção.']}, {'id': 'lei-v3-13-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'A pergunta oferecia apenas vídeos ou livros', 'alternativas': ['A pergunta distinguia vídeos, aulas presenciais, exercícios e livros antes de calcular os noventa votos.', 'Os participantes foram selecionados entre estudantes que acompanhavam diferentes tipos de material, sem vínculo com o canal.', 'A pergunta oferecia apenas vídeos ou livros', 'A pesquisa permitia escolher combinações de recursos e indicar preferências diferentes para cada matéria.']}]})
HISTORIAS.append({'id': 'lei-v3-14', 'faixa_etaria': '12-13', 'versao': 3, 'colecao': 'Investigar e argumentar', 'tema': 'O conserto antes da compra', 'titulo': 'O conserto antes da compra', 'nivel': 'intermediario', 'nivel_numerico': 4, 'vocabulario': ['diagnóstico', 'equipamentos', 'custos', 'reparo'], 'paginas': ['O laboratório tinha seis computadores lentos. Uma proposta sugeria substituir todos os equipamentos. Outra defendia fazer manutenção antes de comprar máquinas novas. No debate inicial, cada grupo apresentou apenas o valor de sua solução preferida.', 'A equipe técnica examinou os computadores e encontrou situações diferentes: dois apresentavam defeitos no armazenamento, três precisavam de atualização e limpeza, e um já não atendia às necessidades das aulas. Também verificou a disponibilidade de peças e o tempo em que o laboratório ficaria parado.', 'Com o diagnóstico, a escola montou um plano combinado. Recuperaria parte dos equipamentos e substituiria o que não comportava as tarefas previstas. A economia estimada não foi tratada como garantida: algumas peças ainda precisavam ser orçadas, e reparos poderiam revelar outros defeitos. A proposta incluiu um limite de gasto para decidir quando um conserto deixaria de compensar.', 'A decisão final não premiou automaticamente a opção com menor preço inicial. Considerou uso esperado, duração, manutenção e interrupções. O relatório destacou ainda a destinação adequada das peças retiradas. Comparar soluções significou tornar visíveis custos e consequências que um único número no orçamento escondia.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'continuacao', 'titulo': 'Crie uma continuação coerente', 'instrucao': 'Imagine uma nova etapa para essa situação. Preserve os fatos e participantes do texto, apresente um novo problema e explique como ele se desenvolve.', 'minimo_palavras': 55, 'palavras_contexto': ['diagnóstico', 'equipamentos', 'custos', 'reparo']}, 'perguntas': [{'id': 'lei-v3-14-q1', 'enunciado': 'Por que escolher apenas pelo menor preço inicial seria insuficiente?', 'correta': 'Os computadores tinham problemas e necessidades diferentes', 'alternativas': ['Os computadores tinham problemas e necessidades diferentes', 'Porque reparos nunca têm custos ou riscos', 'Porque a escola não utilizava os computadores', 'Porque todos os equipamentos tinham exatamente o mesmo defeito']}, {'id': 'lei-v3-14-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'A decisão precisa considerar diagnóstico e custos ao longo do uso', 'alternativas': ['Recuperar parte das máquinas tornou a economia garantida, mesmo sem os orçamentos das peças necessárias.', 'O menor preço inicial bastaria para comparar as soluções, pois manutenção e paralisação não alteravam os gastos.', 'A decisão precisa considerar diagnóstico e custos ao longo do uso', 'O diagnóstico mostrou que substituir todos os equipamentos seria a alternativa de menor custo em qualquer cenário.']}, {'id': 'lei-v3-14-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'A escola combinou reparo de parte das máquinas com substituição de outra', 'alternativas': ['A escola combinou reparo de parte das máquinas com substituição de outra', 'As peças já estavam integralmente orçadas quando a equipe apresentou uma economia como certa.', 'A escola aprovou a recuperação de todas as máquinas sem definir um limite para o custo dos reparos.', 'A inspeção concluiu que todos os computadores tinham o mesmo defeito e precisavam da mesma intervenção.']}]})
HISTORIAS.append({'id': 'lei-v3-15', 'faixa_etaria': '12-13', 'versao': 3, 'colecao': 'Investigar e argumentar', 'tema': 'A água medida em dias diferentes', 'titulo': 'A água medida em dias diferentes', 'nivel': 'intermediario', 'nivel_numerico': 4, 'vocabulario': ['consumo', 'medidas', 'presença', 'comparação'], 'paginas': ['Dois grupos compararam o consumo de água da escola antes e depois de uma campanha. O primeiro leu o medidor em uma sexta-feira de atividades normais. O segundo fez a leitura em uma segunda-feira com metade das turmas em passeio. O consumo caiu, e um cartaz atribuiu toda a redução à campanha.', 'Uma estudante perguntou se o número de pessoas presentes poderia ter influenciado o resultado. A pergunta não provava que a campanha havia falhado. Indicava que os dados disponíveis não permitiam separar todos os fatores.', 'A turma reorganizou o acompanhamento. Passou a registrar períodos de mesma duração, presença de estudantes, limpeza extraordinária e vazamentos identificados. Também comparou mais de uma semana, reconhecendo que o consumo poderia variar por motivos diferentes. Depois dessas observações, encontrou uma redução menor, mas mais consistente com as ações propostas.', 'No novo cartaz, apresentou o período de medição e as limitações da análise. O resultado ficou menos impressionante e mais informativo. A turma aprendeu a distinguir uma diferença observada de uma explicação comprovada. Para sustentar uma conclusão, não basta que dois acontecimentos ocorram próximos: é preciso examinar o que mais mudou entre as medidas.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'comparacao', 'titulo': 'Compare as escolhas', 'instrucao': 'Compare duas escolhas, interpretações ou momentos apresentados na leitura. Explique uma diferença, uma consequência e a informação que sustenta sua comparação.', 'minimo_palavras': 55, 'palavras_contexto': ['consumo', 'medidas', 'presença', 'comparação']}, 'perguntas': [{'id': 'lei-v3-15-q1', 'enunciado': 'Qual fator confundiu a comparação inicial?', 'correta': 'O número de pessoas presentes mudou entre os períodos', 'alternativas': ['O medidor sempre transforma água em porcentagens', 'O número de pessoas presentes mudou entre os períodos', 'A campanha não aconteceu em nenhum momento', 'As duas medidas cobriram condições idênticas comprovadas']}, {'id': 'lei-v3-15-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Uma diferença entre medidas não comprova sozinha sua causa', 'alternativas': ['Uma redução menor no acompanhamento posterior tornou os novos dados menos úteis do que o cartaz inicial.', 'A presença menor na segunda leitura comprovou que a campanha não produziu efeito algum no consumo.', 'Uma diferença entre medidas não comprova sozinha sua causa', 'A proximidade entre a campanha e a queda no consumo demonstrou que toda a diferença foi causada por ela.']}, {'id': 'lei-v3-15-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'O acompanhamento posterior registrou presença e períodos equivalentes', 'alternativas': ['A primeira comparação registrou a mesma presença de estudantes nos dois períodos medidos.', 'O acompanhamento posterior desconsiderou os vazamentos e a limpeza para manter a comparação simples.', 'O acompanhamento posterior registrou presença e períodos equivalentes', 'A turma repetiu somente as mesmas duas leituras iniciais, sem acompanhar outras semanas.']}]})
HISTORIAS.append({'id': 'lei-v3-16', 'faixa_etaria': '12-13', 'versao': 3, 'colecao': 'Investigar e argumentar', 'tema': 'A decisão sobre o telhado', 'titulo': 'A decisão sobre o telhado', 'nivel': 'intermediario', 'nivel_numerico': 4, 'vocabulario': ['propostas', 'escopo', 'critérios', 'transparência'], 'paginas': ['Um centro comunitário recebeu duas propostas para consertar seu telhado. A primeira custava menos e prometia terminar rapidamente. A segunda incluía inspeção da estrutura, descrição dos materiais e garantia escrita. Parte dos moradores queria escolher imediatamente a proposta mais barata, pois a chuva já havia causado prejuízos.', 'Na reunião, uma moradora perguntou se os dois documentos cobriam o mesmo serviço. A comparação revelou que a primeira proposta previa apenas trocar algumas telhas. A inspeção poderia mostrar problemas adicionais que seriam cobrados à parte. A segunda também tinha limites, mas os descrevia com mais clareza.', 'O conselho pediu esclarecimentos aos dois fornecedores, consultou referências e solicitou uma avaliação técnica. Enquanto aguardava, organizou uma medida provisória indicada por profissional responsável. A urgência foi considerada, sem ser usada como motivo para ignorar informações essenciais.', 'Ao publicar a decisão, o conselho mostrou os critérios e as condições contratadas. Alguns moradores continuaram discordando do gasto, mas puderam discutir os mesmos dados. O processo evidenciou que transparência não elimina todo conflito. Ela permite compreender as razões, identificar responsabilidades e cobrar o que foi combinado.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'resumo', 'titulo': 'Reconstrua a ideia principal', 'instrucao': 'Apresente o tema e as informações essenciais. Explique como as ideias ou acontecimentos se relacionam, usando suas palavras.', 'minimo_palavras': 55, 'palavras_contexto': ['propostas', 'escopo', 'critérios', 'transparência']}, 'perguntas': [{'id': 'lei-v3-16-q1', 'enunciado': 'Qual foi o primeiro obstáculo para comparar os preços?', 'correta': 'Os orçamentos inicialmente cobriam serviços diferentes', 'alternativas': ['Os orçamentos inicialmente cobriam serviços diferentes', 'Os documentos descreviam exatamente o mesmo escopo', 'Nenhum morador conhecia a existência do telhado', 'A proposta maior dispensava qualquer verificação']}, {'id': 'lei-v3-16-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Propostas precisam ser comparadas pelo escopo e pelas condições, além do preço', 'alternativas': ['A publicação dos critérios eliminou as discordâncias e comprovou que a proposta escolhida não tinha limites.', 'A proposta mais barata cobria o mesmo serviço, pois ambas mencionavam o conserto do telhado.', 'Propostas precisam ser comparadas pelo escopo e pelas condições, além do preço', 'A urgência da chuva permitia decidir pelo menor preço antes de esclarecer o serviço contratado.']}, {'id': 'lei-v3-16-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'O conselho pediu esclarecimentos e uma avaliação técnica', 'alternativas': ['A medida provisória foi adotada como substituta definitiva da avaliação técnica solicitada.', 'Os moradores decidiram sem pedir esclarecimentos porque os limites das duas propostas eram idênticos.', 'O conselho verificou que o primeiro orçamento já incluía todos os problemas que a inspeção pudesse revelar.', 'O conselho pediu esclarecimentos e uma avaliação técnica']}]})
HISTORIAS.append({'id': 'lei-v3-17', 'faixa_etaria': '12-13', 'versao': 3, 'colecao': 'Investigar e argumentar', 'tema': 'O vídeo que parecia uma prova', 'titulo': 'O vídeo que parecia uma prova', 'nivel': 'intermediario', 'nivel_numerico': 4, 'vocabulario': ['vídeo', 'contexto', 'fontes', 'versões'], 'paginas': ['Um vídeo de quinze segundos mostrava uma discussão na entrada de um ginásio. A publicação afirmava que o funcionário havia impedido um estudante de participar por antipatia. O trecho começava no meio de uma frase e terminava antes da resposta completa.', 'Ao preparar uma matéria para o jornal escolar, Lucas procurou a gravação integral e ouviu as pessoas envolvidas. Descobriu que havia uma divergência sobre a autorização necessária. Isso não resolveu automaticamente se a abordagem do funcionário fora adequada, mas alterou o contexto da acusação inicial.', 'Na reportagem, Lucas separou fatos confirmados, versões das pessoas e perguntas ainda sem resposta. Evitou apresentar uma opinião como se fosse uma conclusão demonstrada pelo vídeo. Também explicou por que não publicaria nomes de estudantes sem necessidade.', 'Alguns leitores pediram um título que apontasse imediatamente um culpado. A equipe preferiu descrever o conflito e informar o que estava sendo apurado. A escolha exigiu resistir à pressa de encerrar uma história incompleta. Um registro audiovisual pode ser uma fonte importante, mas seu enquadramento e sua duração determinam parte do que o público consegue conhecer.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'opiniao', 'titulo': 'Defenda uma posição', 'instrucao': 'Defenda uma posição sobre a situação ou a ideia principal da leitura. Apresente duas razões e uma informação concreta do texto. Considere também uma possível objeção.', 'minimo_palavras': 55, 'palavras_contexto': ['vídeo', 'contexto', 'fontes', 'versões']}, 'perguntas': [{'id': 'lei-v3-17-q1', 'enunciado': 'Por que Lucas buscou outras fontes além do trecho publicado?', 'correta': 'A gravação começava no meio da conversa e terminava antes da resposta', 'alternativas': ['Porque a publicação já mostrava toda a conversa', 'Porque imagens nunca registram acontecimentos reais', 'A gravação começava no meio da conversa e terminava antes da resposta', 'Porque ouvir versões impede qualquer apuração']}, {'id': 'lei-v3-17-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Um recorte de vídeo pode omitir contexto necessário para avaliar um conflito', 'alternativas': ['A gravação integral provou automaticamente que a abordagem do funcionário havia sido adequada.', 'Um recorte de vídeo pode omitir contexto necessário para avaliar um conflito', 'O trecho de quinze segundos era suficiente para atribuir o conflito à antipatia do funcionário.', 'Ouvir as pessoas transformou todas as versões apresentadas em fatos igualmente confirmados.']}, {'id': 'lei-v3-17-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'A gravação integral revelou uma divergência sobre autorização', 'alternativas': ['Lucas manteve a acusação inicial porque as outras fontes não acrescentaram contexto à discussão.', 'A gravação integral revelou uma divergência sobre autorização', 'A gravação publicada incluía a conversa completa sobre a autorização e a resposta do funcionário.', 'A apuração confirmou que a autorização já havia sido apresentada e não era motivo de divergência.']}]})
HISTORIAS.append({'id': 'lei-v3-18', 'faixa_etaria': '12-13', 'versao': 3, 'colecao': 'Investigar e argumentar', 'tema': 'O aplicativo de pontos', 'titulo': 'O aplicativo de pontos', 'nivel': 'intermediario', 'nivel_numerico': 5, 'vocabulario': ['pontos', 'tarefas', 'aprendizagem', 'indicadores'], 'paginas': ['Uma turma testou um aplicativo que premiava tarefas concluídas com pontos. Nas primeiras semanas, o número de atividades entregues aumentou. A direção considerou anunciar que o aplicativo havia melhorado a aprendizagem de todos.', 'Antes de divulgar a conclusão, a professora comparou respostas, tipos de erro e trabalhos realizados sem o aplicativo. Descobriu que alguns estudantes repetiam tarefas fáceis para acumular pontos. Outros resolviam menos itens, mas escolhiam desafios e explicavam melhor suas estratégias. O total de pontos reunia comportamentos muito diferentes.', 'A equipe decidiu separar indicadores: participação, quantidade de tarefas e domínio das habilidades. Também passou a observar se os estudantes aplicavam o que aprenderam em situações novas. Nenhum indicador isolado respondia a todas as perguntas.', 'O aplicativo continuou em teste, com regras revistas para não recompensar apenas volume. A mudança não significou que pontos fossem inúteis; eles poderiam incentivar a rotina. O problema era usá-los como prova suficiente de compreensão. No relatório, a turma propôs que resultados automáticos fossem acompanhados de exemplos de raciocínio e oportunidades de revisão. Medir algo de maneira exata não garante que esse algo represente o objetivo que se pretende alcançar.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'continuacao', 'titulo': 'Crie uma continuação coerente', 'instrucao': 'Imagine uma nova etapa para essa situação. Preserve os fatos e participantes do texto, apresente um novo problema e explique como ele se desenvolve.', 'minimo_palavras': 55, 'palavras_contexto': ['pontos', 'tarefas', 'aprendizagem', 'indicadores']}, 'perguntas': [{'id': 'lei-v3-18-q1', 'enunciado': 'Qual distinção é central para avaliar o aplicativo?', 'correta': 'Alguns estudantes repetiam tarefas fáceis para acumular pontos', 'alternativas': ['Qualquer incentivo impede a aprendizagem', 'Alguns estudantes repetiam tarefas fáceis para acumular pontos', 'Uma tarefa difícil sempre precisa valer zero', 'Todos os pontos demonstravam o mesmo tipo de compreensão']}, {'id': 'lei-v3-18-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Quantidade de tarefas e pontos não equivalem necessariamente a aprendizagem', 'alternativas': ['O aumento de entregas demonstrou que todos os estudantes passaram a dominar melhor as habilidades.', 'Quantidade de tarefas e pontos não equivalem necessariamente a aprendizagem', 'Separar indicadores tornou os pontos inúteis até mesmo como incentivo para manter uma rotina de estudos.', 'Os estudantes com menos pontos necessariamente aprenderam menos, mesmo explicando melhor suas estratégias.']}, {'id': 'lei-v3-18-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'Outros faziam menos itens e explicavam melhor suas estratégias', 'alternativas': ['Outros faziam menos itens e explicavam melhor suas estratégias', 'A professora verificou que quem acumulava mais pontos escolhia sempre as tarefas mais difíceis.', 'Os trabalhos sem aplicativo confirmaram o mesmo domínio entre todos os estudantes que entregaram mais itens.', 'A análise encontrou aumento de entregas sem qualquer repetição de tarefas fáceis entre os participantes.']}]})
HISTORIAS.append({'id': 'lei-v3-19', 'faixa_etaria': '12-13', 'versao': 3, 'colecao': 'Investigar e argumentar', 'tema': 'O bairro visto pela média', 'titulo': 'O bairro visto pela média', 'nivel': 'intermediario', 'nivel_numerico': 5, 'vocabulario': ['média', 'dados', 'grupos', 'diferenças'], 'paginas': ['Um levantamento calculou o tempo médio de espera pelos ônibus de um bairro. O resultado parecia razoável e foi usado para afirmar que o atendimento era adequado. Moradores de uma rua distante do terminal contestaram a conclusão: para eles, a espera frequentemente ultrapassava o dobro do valor anunciado.', 'Ao examinar os registros, a equipe encontrou muitas observações perto do terminal e poucas nas ruas mais afastadas. Também percebeu diferenças entre horários de pico, noites e fins de semana. A média não estava necessariamente calculada de forma errada; ela reunia experiências que precisavam ser examinadas separadamente.', 'O relatório seguinte apresentou resultados por local e período, com o número de observações de cada grupo. Informou ainda que algumas áreas tinham dados insuficientes. A apresentação ficou mais longa e não permitiu uma única frase tão simples quanto a anterior.', "Para os moradores, isso tornou a discussão mais concreta. Em vez de disputar se a média era 'boa' ou 'ruim', puderam identificar onde faltavam viagens e quando a espera aumentava. Resumir dados é necessário, mas um resumo pode esconder diferenças importantes. Escolher como agrupar informações também é escolher quais problemas ficarão visíveis."], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'comparacao', 'titulo': 'Compare as escolhas', 'instrucao': 'Compare duas escolhas, interpretações ou momentos apresentados na leitura. Explique uma diferença, uma consequência e a informação que sustenta sua comparação.', 'minimo_palavras': 55, 'palavras_contexto': ['média', 'dados', 'grupos', 'diferenças']}, 'perguntas': [{'id': 'lei-v3-19-q1', 'enunciado': 'Como uma média correta pode sustentar uma conclusão incompleta?', 'correta': 'Havia mais observações perto do terminal e diferenças entre horários', 'alternativas': ['Porque toda operação de média produz um número falso', 'Havia mais observações perto do terminal e diferenças entre horários', 'Porque o bairro não tinha usuários de ônibus', 'Porque observar locais diferentes elimina toda diferença']}, {'id': 'lei-v3-19-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Uma média pode esconder diferenças relevantes entre grupos e períodos', 'alternativas': ['A reclamação dos moradores demonstrou um erro aritmético no cálculo da média original.', 'Separar os dados por local eliminou a necessidade de informar quantas observações existiam em cada grupo.', 'Uma média calculada corretamente assegura que todos os locais e horários recebam atendimento adequado.', 'Uma média pode esconder diferenças relevantes entre grupos e períodos']}, {'id': 'lei-v3-19-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'O novo relatório separou resultados por local e período', 'alternativas': ['O novo relatório separou resultados por local e período', 'O novo relatório substituiu os recortes locais por uma única média para todo o bairro.', 'A primeira coleta reuniu quantidades equivalentes de observações em todas as ruas e períodos.', 'Os registros mostraram que horários noturnos e de pico tinham sempre a mesma espera.']}]})
HISTORIAS.append({'id': 'lei-v3-20', 'faixa_etaria': '12-13', 'versao': 3, 'colecao': 'Investigar e argumentar', 'tema': 'A biblioteca e os registros digitais', 'titulo': 'A biblioteca e os registros digitais', 'nivel': 'intermediario', 'nivel_numerico': 5, 'vocabulario': ['dados', 'recomendações', 'escolha', 'diversidade'], 'paginas': ['A biblioteca queria recomendar livros a partir do histórico de empréstimos. O projeto prometia facilitar descobertas e reduzir o tempo de busca. Na apresentação inicial, a equipe tratou a coleta de mais dados como um benefício automático.', 'Um grupo de estudantes perguntou quais informações seriam necessárias, quem teria acesso e por quanto tempo ficariam guardadas. Também quis saber se alguém poderia usar a biblioteca sem receber recomendações. Essas perguntas não demonstravam rejeição à tecnologia; procuravam compreender suas condições de uso.', 'O projeto foi revisto para registrar apenas o necessário à finalidade definida. A biblioteca passou a explicar o funcionamento das recomendações, oferecer escolha e estabelecer procedimentos de acesso e exclusão dos registros conforme as regras aplicáveis. A equipe reconheceu que manter informações também cria responsabilidades.', 'No teste, algumas recomendações foram úteis, mas outras limitaram a variedade, oferecendo sempre assuntos parecidos. Os estudantes sugeriram incluir descobertas fora do histórico e permitir que cada leitor ajustasse suas preferências. A discussão mostrou duas dimensões distintas: proteger os registros e avaliar a qualidade das sugestões. Um sistema pode funcionar tecnicamente e ainda precisar de revisão quanto às escolhas que incentiva.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'resumo', 'titulo': 'Reconstrua a ideia principal', 'instrucao': 'Apresente o tema e as informações essenciais. Explique como as ideias ou acontecimentos se relacionam, usando suas palavras.', 'minimo_palavras': 55, 'palavras_contexto': ['dados', 'recomendações', 'escolha', 'diversidade']}, 'perguntas': [{'id': 'lei-v3-20-q1', 'enunciado': 'Por que a revisão precisava considerar mais do que o funcionamento técnico?', 'correta': 'Coletar registros cria responsabilidades e pode limitar as sugestões', 'alternativas': ['Porque qualquer recomendação era obrigatoriamente inútil', 'Porque os leitores tinham preferências idênticas', 'Porque guardar todos os dados dispensava responsabilidades', 'Coletar registros cria responsabilidades e pode limitar as sugestões']}, {'id': 'lei-v3-20-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Recomendações digitais precisam de limites de uso dos dados e avaliação da diversidade', 'alternativas': ['Uma recomendação tecnicamente funcional dispensa avaliar se ela restringe a variedade de leituras.', 'Coletar o maior volume possível de dados é necessário para oferecer escolha aos usuários da biblioteca.', 'Proteger os registros dos leitores é suficiente para assegurar também a qualidade de todas as sugestões.', 'Recomendações digitais precisam de limites de uso dos dados e avaliação da diversidade']}, {'id': 'lei-v3-20-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'O teste oferecia repetidamente assuntos parecidos', 'alternativas': ['Os estudantes limitaram a revisão ao tempo de busca e deixaram de questionar o acesso aos dados.', 'O teste confirmou que guardar mais registros sempre apresentava aos leitores assuntos fora de suas preferências.', 'A revisão passou a exigir recomendações obrigatórias para qualquer pessoa que usasse a biblioteca.', 'O teste oferecia repetidamente assuntos parecidos']}]})
HISTORIAS.append({'id': 'lei-v3-21', 'faixa_etaria': '12-13', 'versao': 3, 'colecao': 'Investigar e argumentar', 'tema': 'Uma obra e duas formas de contar', 'titulo': 'Uma obra e duas formas de contar', 'nivel': 'intermediario', 'nivel_numerico': 5, 'vocabulario': ['reportagens', 'perspectivas', 'evidências', 'consequências'], 'paginas': ['A reforma de uma praça recebeu duas reportagens. Uma destacou que a obra criaria novos espaços de esporte. A outra apresentou reclamações de moradores sobre a retirada temporária de bancos e o barulho. Em uma discussão na escola, alguns estudantes afirmaram que as notícias não podiam ser verdadeiras ao mesmo tempo.', 'A professora pediu que identificassem quais fatos cada texto apresentava e quais informações deixava em segundo plano. Os alunos perceberam que uma mesma intervenção podia produzir benefícios esperados e transtornos atuais. Isso não tornava todas as interpretações igualmente bem fundamentadas: era necessário conferir fontes, números e promessas.', 'A turma consultou o cronograma divulgado e procurou distinguir resultado previsto de resultado já observado. Descobriu também uma pergunta ausente nas duas matérias: como ficaria a circulação de pessoas com mobilidade reduzida durante a obra.', 'No trabalho final, os estudantes escreveram uma síntese com convergências, diferenças e questões pendentes. Evitaram somar opiniões como se isso produzisse automaticamente uma visão completa. Comparar perspectivas exigiu examinar evidências e reconhecer limites. Uma informação pode ser verdadeira e ainda assim insuficiente para avaliar o conjunto de consequências de uma decisão.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'opiniao', 'titulo': 'Defenda uma posição', 'instrucao': 'Defenda uma posição sobre a situação ou a ideia principal da leitura. Apresente duas razões e uma informação concreta do texto. Considere também uma possível objeção.', 'minimo_palavras': 55, 'palavras_contexto': ['reportagens', 'perspectivas', 'evidências', 'consequências']}, 'perguntas': [{'id': 'lei-v3-21-q1', 'enunciado': 'Por que as duas reportagens não eram necessariamente contraditórias?', 'correta': 'As reportagens tratavam de benefícios previstos e transtornos atuais', 'alternativas': ['Porque opiniões diferentes dispensam evidências', 'Porque a reforma não tinha consequências', 'As reportagens tratavam de benefícios previstos e transtornos atuais', 'Porque toda promessa já era um resultado comprovado']}, {'id': 'lei-v3-21-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Perspectivas diferentes podem destacar aspectos verdadeiros sem esgotar o assunto', 'alternativas': ['Como as matérias apresentavam perspectivas diferentes, nenhuma delas podia conter fatos verdadeiros.', 'Somar as duas reportagens produzia uma visão completa das consequências da obra para todos os moradores.', 'Perspectivas diferentes podem destacar aspectos verdadeiros sem esgotar o assunto', 'O benefício esportivo previsto tornava falsas as reclamações sobre o transtorno atual da reforma.']}, {'id': 'lei-v3-21-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'A turma identificou uma questão de acessibilidade ausente nas duas matérias', 'alternativas': ['A turma identificou uma questão de acessibilidade ausente nas duas matérias', 'O cronograma mostrou que não haveria transtornos atuais durante a execução da obra.', 'A turma verificou que os novos espaços esportivos estavam concluídos antes do começo da reforma.', 'As duas matérias já explicavam de forma completa a circulação de pessoas com mobilidade reduzida.']}]})
HISTORIAS.append({'id': 'lei-v3-22', 'faixa_etaria': '12-13', 'versao': 3, 'colecao': 'Investigar e argumentar', 'tema': 'O orçamento do festival', 'titulo': 'O orçamento do festival', 'nivel': 'intermediario', 'nivel_numerico': 5, 'vocabulario': ['orçamento', 'estimativas', 'cenários', 'compromissos'], 'paginas': ['O grêmio planejou um festival com apresentações, oficinas e uma feira de projetos. O orçamento inicial considerou ingressos vendidos como se todas as pessoas convidadas fossem comparecer. Com essa previsão, parecia possível contratar a estrutura mais cara e ainda guardar dinheiro para o próximo evento.', 'Uma comissão pediu que a equipe separasse valores confirmados, estimativas e despesas que aconteceriam mesmo com público pequeno. Também propôs comparar cenários de participação. O exercício mostrou que uma redução moderada na venda de ingressos poderia comprometer pagamentos já assumidos.', 'O planejamento foi reorganizado. Alguns contratos passaram a depender de confirmação prévia, e o grêmio buscou alternativas de menor custo para despesas fixas. A equipe definiu um prazo para decidir o tamanho do evento e publicou as condições de devolução de valores.', 'O festival não perdeu seu objetivo por trabalhar com hipóteses mais cuidadosas. Ganhou critérios para adaptar o projeto antes de assumir compromissos maiores. No balanço, o grêmio comparou previsão e resultado, procurando explicar as diferenças. Planejar não significa prever o futuro com certeza. Significa reconhecer incertezas, avaliar suas consequências e escolher ações que continuem viáveis quando parte das expectativas não se realiza.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'continuacao', 'titulo': 'Crie uma continuação coerente', 'instrucao': 'Imagine uma nova etapa para essa situação. Preserve os fatos e participantes do texto, apresente um novo problema e explique como ele se desenvolve.', 'minimo_palavras': 55, 'palavras_contexto': ['orçamento', 'estimativas', 'cenários', 'compromissos']}, 'perguntas': [{'id': 'lei-v3-22-q1', 'enunciado': 'Qual risco foi revelado pela comparação de cenários?', 'correta': 'O orçamento tratava todos os convidados como compradores certos', 'alternativas': ['Toda estimativa se tornaria automaticamente um valor confirmado', 'Qualquer número de participantes garantiria a mesma receita', 'As despesas fixas desapareceriam sem público', 'O orçamento tratava todos os convidados como compradores certos']}, {'id': 'lei-v3-22-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'Planejamento financeiro precisa separar estimativas de receitas confirmadas e testar cenários', 'alternativas': ['Considerar todos os convidados como compradores tornava a receita inicial um valor já confirmado.', 'Vincular alguns contratos à confirmação garantia que toda despesa desapareceria quando a receita caísse.', 'Planejamento financeiro precisa separar estimativas de receitas confirmadas e testar cenários', 'O planejamento cuidadoso retirou a necessidade de adaptar o evento se o público fosse menor.']}, {'id': 'lei-v3-22-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'Uma queda moderada no público comprometeria pagamentos assumidos', 'alternativas': ['O grêmio verificou que todos os convidados já tinham comprado os ingressos antes do orçamento inicial.', 'Uma queda moderada no público comprometeria pagamentos assumidos', 'Os diferentes cenários mostraram que qualquer redução de público manteria viáveis todos os pagamentos.', 'A comparação confirmou que as despesas fixas diminuiriam na mesma proporção da venda de ingressos.']}]})
HISTORIAS.append({'id': 'lei-v3-23', 'faixa_etaria': '12-13', 'versao': 3, 'colecao': 'Investigar e argumentar', 'tema': 'O experimento que não confirmou a ideia', 'titulo': 'O experimento que não confirmou a ideia', 'nivel': 'intermediario', 'nivel_numerico': 5, 'vocabulario': ['teste', 'ordem', 'prática', 'hipótese'], 'paginas': ['Uma equipe investigou se ouvir determinada música melhorava o desempenho em um jogo de memória. Os participantes fizeram uma rodada em silêncio e outra com música. Como quase todos foram melhores na segunda rodada, o grupo anunciou que a música havia causado a melhora.', 'Na revisão, outra equipe perguntou se a prática adquirida na primeira tentativa poderia explicar parte da diferença. Também observou que todos haviam realizado as condições na mesma ordem. O resultado era compatível com mais de uma explicação.', 'O grupo refez o planejamento: alternou a ordem das condições, usou conjuntos equivalentes de cartas e registrou diferenças individuais. O novo resultado não mostrou uma vantagem consistente para a música naquele teste. Alguns participantes melhoraram; outros tiveram desempenho semelhante ou pior.', 'A equipe precisou decidir se esconderia o segundo resultado para manter uma apresentação mais impressionante. Preferiu mostrar as duas etapas e explicar o que havia aprendido. A revisão não transformou o trabalho em fracasso. Produziu uma conclusão mais limitada e um método mais cuidadoso. Investigar uma hipótese exige aceitar que observações novas podem enfraquecê-la. A qualidade do trabalho depende também de como se lida com resultados que não confirmam a expectativa inicial.'], 'reflexao': 'Que informação do texto ajuda a justificar sua resposta?', 'proposta': {'tipo': 'comparacao', 'titulo': 'Compare as escolhas', 'instrucao': 'Compare duas escolhas, interpretações ou momentos apresentados na leitura. Explique uma diferença, uma consequência e a informação que sustenta sua comparação.', 'minimo_palavras': 55, 'palavras_contexto': ['teste', 'ordem', 'prática', 'hipótese']}, 'perguntas': [{'id': 'lei-v3-23-q1', 'enunciado': 'Por que a melhora inicial não provava um efeito da música?', 'correta': 'Todos fizeram a condição com música depois de praticar em silêncio', 'alternativas': ['Todos fizeram a condição com música depois de praticar em silêncio', 'Porque os participantes nunca tinham feito o jogo', 'Porque a ordem era irrelevante por definição', 'Porque resultados contrários devem ser escondidos']}, {'id': 'lei-v3-23-q2', 'enunciado': 'Qual conclusão é sustentada pelo texto?', 'correta': 'A ordem dos testes e a prática podem confundir uma explicação causal', 'alternativas': ['O teste revisto demonstrou que ouvir música piora a memória de qualquer participante em qualquer situação.', 'A ordem dos testes e a prática podem confundir uma explicação causal', 'Resultados que enfraquecem a hipótese inicial indicam que o experimento deve ser omitido da apresentação.', 'O resultado inicial isolou o efeito da música porque todos os participantes fizeram as condições na mesma ordem.']}, {'id': 'lei-v3-23-q3', 'enunciado': 'Qual informação ajuda a sustentar a análise?', 'correta': 'O teste com ordem alternada não encontrou vantagem consistente', 'alternativas': ['A primeira experiência alternou a ordem das condições para separar a prática do possível efeito da música.', 'O teste com ordem alternada não encontrou vantagem consistente', 'O teste revisto confirmou a mesma vantagem da música para todos os participantes e condições.', 'Os participantes apresentaram resultados individuais idênticos depois da mudança no planejamento.']}]})



